def tm_cta_warps(p, hw, cfg) -> float:
    """log2 of warps in one CTA barrier domain. Larger is worse."""
    return math.log2(max(1.0, cfg.threads / 32.0))

def tm_regstaged(p, hw, cfg) -> float:
    """1 for the register-staged two-stage mainloop (one iteration of compute covers each global load), else 0."""
    return 1.0 if cfg.stages <= 2 else 0.0

def tm_log_inst(p, hw, cfg) -> float:
    """log2 of the static SASS instruction count (code footprint)."""
    return math.log2(max(1.0, float(cfg.inst_total)))

def splitk_sm_latency_rounds_log(p, hw, cfg) -> float:
    """log2 of the memory round trips the busiest SM must serialise: its n=ceil(tiles*sk/SMs) CTAs stream n*ceil(K/(tk*sk)) k-steps, while only min(n, blocks/SM)*(stages-1) k-step loads can be in flight at once (Little's law). Larger is worse."""
    s = max(1, cfg.split_k); T = math.ceil(p.M / cfg.tile_m) * math.ceil(p.N / cfg.tile_n); n = math.ceil(T * s / hw.sm_count)
    steps = n * math.ceil(p.K / (cfg.tile_k * s))
    inflight = min(n, max(1, cfg.max_blocks_per_sm)) * max(1, cfg.stages - 1)
    return math.log2(max(1.0, steps / inflight))
